+        self::assertArrayHasKey('token', $challenge);
+        self::assertNotEmpty($challenge['image']);
+
+        $row = $connection->fetchAssociative('SELECT challenge_payload FROM captcha_challenges WHERE token = :token', ['token' => $challenge['token']]);
