+
+        self::assertTrue($captchaService->verify($challenge['token'], (string) $payload['answer']));
+
+        $challenge2 = $captchaService->generateChallenge();
+        self::assertFalse($captchaService->verify($challenge2['token'], 'wrong-answer'));
